import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, CircleGeometry, PointLight } = ctx.THREE;
  const root = new Group();
  const timelines = [];
  const primitiveResults = [];
  const ownedResources = [];
  const handlers = {};

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const rgb = (hex) => {
    const value = hex.replace('#', '');
    return vec3(
      parseInt(value.slice(0, 2), 16) / 255,
      parseInt(value.slice(2, 4), 16) / 255,
      parseInt(value.slice(4, 6), 16) / 255
    );
  };

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  const backdropUv = uv();
  backdropMaterial.colorNode = mix(
    rgb(colors.surface),
    mix(rgb(colors.ink), rgb(colors.accent), backdropUv.y.mul(0.045)),
    backdropUv.y.mul(0.72)
  );
  backdropMaterial.depthWrite = false;
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  ownedResources.push(backdropGeometry, backdropMaterial);

  const panelGeometry = new BoxGeometry(2.45, 1.38, 0.16);
  const panelMaterial = new MeshStandardNodeMaterial({
    color: colors.ink,
    roughness: 0.62,
    metalness: 0.48
  });
  const panel = new Mesh(panelGeometry, panelMaterial);
  panel.position.set(0, 0, -0.28);
  root.add(panel);
  ownedResources.push(panelGeometry, panelMaterial);

  const edgeGeometry = new BoxGeometry(2.5, 0.035, 0.025);
  const edgeMaterial = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.42
  });
  const accentEdge = new Mesh(edgeGeometry, edgeMaterial);
  accentEdge.position.set(0, -0.69, -0.17);
  root.add(accentEdge);
  ownedResources.push(edgeGeometry, edgeMaterial);

  const shadowGeometry = new CircleGeometry(1.35, 48);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const contactShadow = new Mesh(shadowGeometry, shadowMaterial);
  contactShadow.scale.set(1.45, 0.42, 1);
  contactShadow.position.set(0, -0.78, -0.12);
  contactShadow.rotation.x = -Math.PI / 2;
  root.add(contactShadow);
  ownedResources.push(shadowGeometry, shadowMaterial);

  const rim = new PointLight(colors.accent, 0.72, 4.5, 2);
  rim.position.set(1.5, 1.2, 1.8);
  root.add(rim);

  const fill = new PointLight(colors.paper, 0.42, 4, 2);
  fill.position.set(-1.8, 0.6, 1.5);
  root.add(fill);

  const meshHolder = new Group();
  meshHolder.position.set(0, 0.08, 0.08);
  root.add(meshHolder);

  const items = config.textContent ?? visualSpec.textContent ?? [];
  for (const item of items) {
    if (typeof item?.text !== 'string') continue;
    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize,
      color: item.role === 'accent' ? colors.accent : colors.paper,
      align: item.typography?.align ?? 'center',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx
    });
    textObject.position.set(0, item.role === 'label' ? -0.38 : 0.16, 0.02);
    root.add(textObject);
  }

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (!gltf?.scene) return;
      meshHolder.add(gltf.scene);
      gltf.scene.traverse((object) => {
        if (!object.isMesh) return;
        object.castShadow = true;
        object.receiveShadow = true;
      });
    }).catch(() => {});
  }

  const entrance = gsap.fromTo(
    root.position,
    { y: -0.12 },
    { y: 0, duration: 0.7, ease: 'power3.out', paused: true }
  );
  entrance.play();
  timelines.push(entrance);

  const settle = gsap.timeline({ paused: true });
  settle.fromTo(
    root.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
  );
  settle.play();
  timelines.push(settle);

  const hoverLift = gsap.timeline({ paused: true });
  hoverLift.to(root.position, {
    y: 0.15,
    duration: 0.3,
    ease: 'power3.out'
  });

  const press = gsap.timeline({ paused: true });
  press.to(root.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'power2.out'
  }).to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.28,
    ease: 'back.out(2)'
  });
  timelines.push(hoverLift, press);

  handlers.hover = () => {
    hoverLift.play();
  };

  handlers.hoverEnd = () => {
    hoverLift.reverse();
  };

  handlers.click = () => {
    press.restart();
    ctx.emit('hub-home.select', {
      node: root,
      source: 'stat-tile'
    });
  };

  handlers.focus = () => {
    gsap.to(edgeMaterial, {
      opacity: 1,
      duration: 0.2,
      ease: 'power2.out'
    });
  };

  handlers.blur = () => {
    gsap.to(edgeMaterial, {
      opacity: 0.42,
      duration: 0.25,
      ease: 'power2.out'
    });
  };

  for (const primitive of config.cinematicPrimitives ?? []) {
    const applyPrimitive = ctx.primitives?.[primitive.name];
    if (typeof applyPrimitive !== 'function') continue;
    const result = applyPrimitive(root, primitive.params ?? {});
    if (result) {
      primitiveResults.push(result);
      if (result.timeline) timelines.push(result.timeline);
    }
  }

  root.userData.handlers = handlers;
  root.userData.cleanup = () => {
    for (const result of primitiveResults) {
      if (typeof result.cleanup === 'function') result.cleanup();
    }

    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }

    root.traverse((object) => {
      if (!object.isMesh) return;
      if (object.geometry && !ownedResources.includes(object.geometry)) {
        object.geometry.dispose?.();
      }
      const materials = Array.isArray(object.material)
        ? object.material
        : [object.material];
      for (const material of materials) {
        if (material && !ownedResources.includes(material)) {
          material.dispose?.();
        }
      }
    });

    for (const resource of ownedResources) {
      resource.dispose?.();
    }
  };

  return root;
}

export default createNode;
